//! Native BUTTON subtrees published through innerHTML.
use super::*;
fn fixture()->(Document,Forms,Page){
 let mut d=crate::html::parse_loaded_document_with_scripting("<body><form id=f action='/result'><input id=neighbor name=neighbor value=seed><div id=mount></div></form><form id=g action='/other'><div id=other></div></form>",true,&||Ok(())).unwrap();
 let mut f=Forms::new(&d);let mut p=Page::new();let l=current();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)
}
fn current()->crate::navigation::Location{crate::navigation::address("https://inner-buttons.test/source",&crate::navigation::Location::home()).unwrap()}
fn id(d:&Document,name:&str)->usize{(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(name)).unwrap()}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->String{let source=format!("var failure=null;try{{{s}}}catch(e){{failure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let Value::String(e)=p.runtime.execute("failure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()else{panic!("Expected refusal: {s}")};e}}}
fn query(d:&Document,f:&Forms,owner:&str,submitter:Option<usize>)->Option<String>{f.submit_request(d,id(d,owner),submitter,&current(),&current()).unwrap().location.url.unwrap().query}

#[test]
fn inner_html_buttons_replacement_defaults_caption_records_and_live_boundaries(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var mount=document.getElementById('mount');mount.textContent='Held';var old=mount.firstChild,r=document.createRange(),walk=document.createNodeIterator(mount,4),watch=new MutationObserver(function(){});r.setStart(old,1);r.setEnd(old,3);if(walk.nextNode()!==old)throw 'old iterator';watch.observe(mount,{childList:true});");let count=f.controls.len();
 run(&mut d,&mut f,&mut p,r#"mount.innerHTML='<button id=plain type=button name=action value=before>  Run <b>now</b> </button><button id=submit name=send value=yes>Send</button><button id=reset type=reset disabled>Reset</button>';var plain=mount.firstChild,submit=mount.childNodes[1],reset=mount.lastChild,rs=watch.takeRecords();if(plain.ownerDocument!==document||plain.parentNode!==mount||!plain.isConnected||plain.type!=='button'||plain.name!=='action'||plain.value!=='before'||plain.form!==document.getElementById('f')||submit.type!=='submit'||reset.type!=='reset'||!reset.disabled||plain.textContent!=='  Run now '||document.getElementById('plain')!==plain||old.parentNode!==null||rs.length!==1||rs[0].target!==mount||rs[0].removedNodes[0]!==old||rs[0].addedNodes.length!==3||rs[0].addedNodes[0]!==plain||rs[0].addedNodes[1]!==submit||r.startContainer!==mount||r.startOffset||r.endContainer!==mount||r.endOffset||walk.nextNode()!==plain.firstChild)throw 'native innerHTML buttons and actual records';plain.value='edited';plain.name='changed';if(plain.getAttribute('value')!=='edited'||plain.name!=='changed')throw 'native new button edits';"#);
 assert_eq!(f.controls.len(),count+3);let c=&f.controls[&id(&d,"plain")];assert_eq!(c.kind,Kind::Button);assert_eq!(c.caption,"Run now");assert_eq!(c.name,"changed");assert_eq!(c.value.text(),"edited");assert_eq!(c.owner,Some(id(&d,"f")));assert_eq!(f.controls[&id(&d,"submit")].kind,Kind::Submit);assert_eq!(f.controls[&id(&d,"reset")].kind,Kind::Reset);assert!(f.controls[&id(&d,"reset")].disabled);
}
#[test]
fn inner_html_buttons_detached_connection_move_submission_reset_clear_and_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var mount=document.getElementById('mount'),holder=document.createElement('div');holder.innerHTML='<button id=created name=send value=payload><span>Send now</span></button>';var button=holder.firstChild;if(button.ownerDocument!==document||button.isConnected||button.form!==null||document.getElementById('created')!==null)throw 'native detached innerHTML';button.value='changed';mount.appendChild(holder);if(button!==document.getElementById('created')||button.form!==document.getElementById('f')||!button.isConnected)throw 'native connection';document.getElementById('neighbor').value='edited';"#);
 let b=id(&d,"created");assert_eq!(query(&d,&f,"f",Some(b)).as_deref(),Some("neighbor=edited&send=changed"));assert_eq!(query(&d,&f,"f",None).as_deref(),Some("neighbor=edited"));
 p.begin_job();run(&mut d,&mut f,&mut p,"button.type='reset';");assert_eq!(f.controls[&b].kind,Kind::Reset);f.reset(id(&d,"f"));p.begin_job();run(&mut d,&mut f,&mut p,"if(document.getElementById('neighbor').value!=='seed')throw 'native reset';button.type='submit';document.getElementById('other').appendChild(button);if(button.form!==document.getElementById('g'))throw 'moved owner';");
 assert_eq!(query(&d,&f,"g",Some(b)).as_deref(),Some("send=changed"));p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('other').innerHTML='';if(button.parentNode!==null||button.isConnected||button.form!==null)throw 'native retirement';mount.innerHTML='<button id=fresh type=button>Fresh</button>';if(document.getElementById('fresh').form!==document.getElementById('f'))throw 'fresh native recovery';");assert_eq!(f.controls[&b].owner,None);assert_eq!(f.controls[&id(&d,"fresh")].caption,"Fresh");assert!(!p.has_navigation_request());
}
#[test]
fn inner_html_buttons_active_caption_association_refusal_no_prefix(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var mount=document.getElementById('mount');mount.textContent='Held';var old=mount.firstChild,watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});");let before=format!("{:?}",d.nodes);let controls=f.controls.len();let commits=p.state.dom_commits;
 for source in ["<button type=button>good</button><button onclick=bad>bad</button>","<button form=f>X</button>","<button command=show-modal commandfor=target>X</button>","<button popovertarget=target>X</button>","<button><input value=inside></button>","<button><svg><rect width=1 height=1/></svg></button>","<button><img src=missing></button>"]{
  p.begin_job();let e=refusal(&mut d,&mut f,&mut p,&format!("mount.innerHTML={source:?};"));assert!(!e.is_empty(),"{source}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls.len(),controls);assert_eq!(p.state.dom_commits,commits);
 }
 p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||mount.firstChild!==old||old.parentNode!==mount||mount.textContent!=='Held')throw 'no refused prefix';mount.innerHTML='<button type=button>Fresh</button>';if(mount.firstChild.type!=='button'||mount.firstChild.form!==document.getElementById('f')||watch.takeRecords().length!==1)throw 'fresh native button';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn inner_html_buttons_quota_refusal_preserves_native_state_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var mount=document.getElementById('mount');mount.textContent='Held';var old=mount.firstChild,watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});");let before=format!("{:?}",d.nodes);let controls=f.controls.len();let commits=p.state.dom_commits;let held=p.state.retained_limit;let nodes=p.state.node_limit;let strings=p.state.limits.host.string_bytes;
 for mode in 0..5{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.limits.host.string_bytes=4};let e=refusal(&mut d,&mut f,&mut p,"mount.innerHTML='<button type=button name=action value=payload><b>Native</b> caption</button>';").to_ascii_lowercase();assert!(e.contains("limit")||e.contains("allowance")||e.contains("storage"),"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls.len(),controls);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=held;p.state.node_limit=nodes;p.state.limits.host.string_bytes=strings;}
 p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||mount.firstChild!==old)throw 'quota no prefix';mount.innerHTML='<button id=recovered type=button>Fresh</button>';if(document.getElementById('recovered')!==mount.firstChild||watch.takeRecords().length!==1)throw 'native quota recovery';");assert_eq!(f.controls.len(),controls+1);assert_eq!(f.controls[&id(&d,"recovered")].caption,"Fresh");
}
